// Service to handle GeoServer time dimension extraction
export class TimeSeriesService {

  static async checkLayerTimeDimension(layerName, workspace = 'geonode', baseUrl = '') {
    try {
      // Use proxy URL instead of direct GeoServer URL
      // The proxy will forward to http://10.150.16.184/geoserver
      const url = `/geoserver/${workspace}/wms?service=WMS&version=1.1.1&request=GetCapabilities`;

      console.log(`[TimeSeriesService] Fetching from proxy URL: ${url}`);

      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'Accept': 'application/xml, text/xml',
        },
        // Don't include credentials to avoid CORS issues
        credentials: 'omit'
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const xmlText = await response.text();
      const parser = new DOMParser();
      const xml = parser.parseFromString(xmlText, "text/xml");

      const parserError = xml.querySelector('parsererror');
      if (parserError) {
        console.error('XML parsing error:', parserError);
        throw new Error('XML parsing error');
      }

      const allLayers = xml.getElementsByTagName("Layer");
      let timeValues = [];

      function findLayer(layers, targetName) {
        for (let i = 0; i < layers.length; i++) {
          const nameElement = layers[i].getElementsByTagName("Name")[0];
          if (nameElement && nameElement.textContent === targetName) {
            return layers[i];
          }

          const nestedLayers = layers[i].getElementsByTagName("Layer");
          if (nestedLayers.length > 0) {
            const found = findLayer(nestedLayers, targetName);
            if (found) return found;
          }
        }
        return null;
      }

      const targetLayer = findLayer(allLayers, layerName);

      if (targetLayer) {
        console.log(`[TimeSeriesService] Found layer: ${layerName}`);

        const dimensions = targetLayer.getElementsByTagName("Dimension");
        for (let j = 0; j < dimensions.length; j++) {
          const dimension = dimensions[j];
          if (dimension.getAttribute("name") === "time") {
            const timeExtentText = dimension.textContent.trim();
            if (timeExtentText) {
              console.log(`[TimeSeriesService] Found Dimension with time values`);
              timeValues = this.parseTimeExtent(timeExtentText);
              break;
            }
          }
        }

        if (timeValues.length === 0) {
          const extents = targetLayer.getElementsByTagName("Extent");
          for (let j = 0; j < extents.length; j++) {
            const extent = extents[j];
            if (extent.getAttribute("name") === "time") {
              const timeExtentText = extent.textContent.trim();
              if (timeExtentText) {
                console.log(`[TimeSeriesService] Found Extent with time values`);
                timeValues = this.parseTimeExtent(timeExtentText);
                break;
              }
            }
          }
        }
      } else {
        console.log(`[TimeSeriesService] Layer ${layerName} not found in capabilities`);
        return this.generateDemoTimeValues();
      }

      if (timeValues && timeValues.length > 0) {
        timeValues.sort();
        console.log(`[TimeSeriesService] Layer ${layerName} has ${timeValues.length} time values`);
        console.log(`[TimeSeriesService] First time: ${timeValues[0]}`);
        console.log(`[TimeSeriesService] Last time: ${timeValues[timeValues.length - 1]}`);
        return timeValues;
      } else {
        console.log(`[TimeSeriesService] No time values found for ${layerName}`);
        return this.generateDemoTimeValues();
      }

    } catch (error) {
      console.error(`[TimeSeriesService] Error checking time dimension for ${layerName}:`, error);
      return this.generateDemoTimeValues();
    }
  }

  static parseTimeExtent(timeExtent) {
    if (!timeExtent) return [];

    console.log(`[TimeSeriesService] Parsing time extent: ${timeExtent.substring(0, 200)}...`);

    // Check if it's a comma-separated list of time values
    if (timeExtent.includes(",") && !timeExtent.includes("/")) {
      const values = timeExtent.split(",").map(date => date.trim());
      console.log(`[TimeSeriesService] Parsed ${values.length} comma-separated values`);
      return values;
    }

    // Check if it's a time range with interval (e.g., start/end/interval)
    if (timeExtent.includes("/")) {
      const parts = timeExtent.split("/");
      if (parts.length === 3) {
        const start = new Date(parts[0]);
        const end = new Date(parts[1]);
        const interval = parts[2];
        const intervalMs = this.parseInterval(interval);

        if (intervalMs > 0 && !isNaN(start.getTime()) && !isNaN(end.getTime())) {
          const timeValues = [];
          let current = start;
          while (current <= end) {
            timeValues.push(current.toISOString());
            current = new Date(current.getTime() + intervalMs);
          }
          console.log(`[TimeSeriesService] Generated ${timeValues.length} values from range`);
          return timeValues;
        }
      }
      return parts;
    }

    console.log(`[TimeSeriesService] Single time value: ${timeExtent}`);
    return [timeExtent];
  }

  static parseInterval(interval) {
    console.log(`[TimeSeriesService] Parsing interval: ${interval}`);

    const hoursMatch = interval.match(/PT(\d+)H/);
    if (hoursMatch) return parseInt(hoursMatch[1]) * 60 * 60 * 1000;

    const minutesMatch = interval.match(/PT(\d+)M/);
    if (minutesMatch) return parseInt(minutesMatch[1]) * 60 * 1000;

    const daysMatch = interval.match(/P(\d+)D/);
    if (daysMatch) return parseInt(daysMatch[1]) * 24 * 60 * 60 * 1000;

    console.log(`[TimeSeriesService] Unknown interval format: ${interval}, defaulting to 1 hour`);
    return 60 * 60 * 1000;
  }

  static generateDemoTimeValues() {
    console.log('[TimeSeriesService] Generating demo time values (this should not happen with proxy)');
    const times = [];
    const startDate = new Date('2026-04-25T00:00:00Z'); // Changed to April 2026
    for (let i = 0; i < 24; i++) {
      const date = new Date(startDate.getTime() + i * 3600000);
      times.push(date.toISOString());
    }
    return times;
  }
}
